fn animation_document(
    entity: &EntityId,
    animation_set: &AssetId,
    motion_slot: &MotionSlotId,
) -> TimelineDocument {
    let mut document = TimelineDocument::new(TimelineTick(48_000));
    document.tracks.push(TimelineTrack {
        id: TimelineTrackId::generate(),
        kind: TimelineTrackKind::Animation,
        name: "Animation".to_owned(),
        enabled: true,
        binding: TimelineBinding {
            entity: Some(entity.clone()),
            asset: Some(animation_set.clone()),
        },
        clips: vec![TimelineClip {
            id: TimelineClipId::generate(),
            start: TimelineTick::ZERO,
            end: TimelineTick(48_000),
            payload: TimelineClipPayload::Animation {
                motion_slot: motion_slot.clone(),
                speed: 2.0,
                looping: true,
            },
        }],
    });
    document
}

fn animation_target(
    world: &mut World,
    animation_set: &AssetId,
    motion_slot: &MotionSlotId,
) -> (Entity, crate::asset::Handle<crate::animation::AnimationClip>) {
    let mut clips = crate::asset::Assets::default();
    let clip = clips.add(crate::animation::AnimationClip {
        duration: 2.0,
        channels: Vec::new(),
        morph_channels: Vec::new(),
        events: Vec::new(),
        skeleton: None,
        skeleton_identity: None,
        root_bone: None,
        contacts: Vec::new(),
    });
    let graph = engine_authoring::CompiledAnimGraph {
        states: vec![engine_authoring::AnimState {
            node_id: engine_authoring::NodeId::generate(),
            motion_slot: Some(motion_slot.clone()),
            playback_mode: engine_authoring::AnimationStatePlaybackMode::Loop,
        }],
        transitions: Vec::new(),
        entry_state: 0,
        compile_warnings: Vec::new(),
    };
    let mut graph_player = AnimGraphPlayer::new(
        graph,
        std::collections::BTreeMap::from([(motion_slot.as_str().to_owned(), clip)]),
    );
    graph_player.set_debug_source(crate::anim_graph::AnimationGraphDebugSource {
        graph_asset: AssetId::generate(),
        graph_id: engine_authoring::GraphId::generate(),
        animation_set_asset: animation_set.clone(),
        transition_edges: Vec::new(),
        motion_bindings: std::collections::BTreeMap::new(),
    });

    let target = world.spawn().expect("entity");
    world
        .add_component(target, Animator::playing(clip))
        .expect("animator");
    world
        .add_component(target, graph_player)
        .expect("animation graph");
    (target, clip)
}

#[test]
fn animation_track_uses_the_bound_set_and_samples_seek_time_exactly() {
    let mut world = World::new();
    let authoring = EntityId::generate();
    let animation_set = AssetId::generate();
    let motion_slot = MotionSlotId::generate();
    let (target, resolved_clip) =
        animation_target(&mut world, &animation_set, &motion_slot);
    let mut bindings = TimelineBindings::default();
    bindings.bind(&authoring, target);

    let timeline = Arc::new(
        compile_timeline(&animation_document(
            &authoring,
            &animation_set,
            &motion_slot,
        ))
        .expect("compile"),
    );
    let player = world.spawn().expect("entity");
    let mut component = TimelinePlayerComponent::new(timeline);
    component.autoplay = true;
    world.add_component(player, component).expect("player");

    let mut camera_override = TimelineCameraOverride::default();
    let mut events = TimelineEvents::default();
    let mut diagnostics = TimelineDiagnostics::default();
    advance_timelines(
        0.25,
        &mut world,
        &bindings,
        &mut camera_override,
        &mut events,
        &mut diagnostics,
    );

    let animator = world.get_component::<Animator>(target).expect("animator");
    assert_eq!(animator.clip, resolved_clip);
    assert!((animator.time - 0.5).abs() < 0.0001);
    assert_eq!(animator.playback_speed, 2.0);
    assert!(animator.looping);
    assert_eq!(animator.state, crate::animation::AnimatorState::Playing);
    assert_eq!(
        world
            .get_component::<AnimGraphPlayer>(target)
            .expect("graph")
            .external_override_owner(),
        Some(player)
    );
    assert!(diagnostics.iter().next().is_none());

    apply_timeline_control(&mut world, player, TimelineControl::Pause).expect("pause");
    apply_timeline_control(
        &mut world,
        player,
        TimelineControl::Seek {
            tick: TimelineTick(36_000),
        },
    )
    .expect("seek");
    advance_timelines(
        0.0,
        &mut world,
        &bindings,
        &mut camera_override,
        &mut events,
        &mut diagnostics,
    );

    let animator = world.get_component::<Animator>(target).expect("animator");
    assert!((animator.time - 1.5).abs() < 0.0001);
    assert_eq!(animator.state, crate::animation::AnimatorState::Paused);

    apply_timeline_control(&mut world, player, TimelineControl::Play).expect("play");
    advance_timelines(
        0.25,
        &mut world,
        &bindings,
        &mut camera_override,
        &mut events,
        &mut diagnostics,
    );
    assert_eq!(
        world
            .get_component::<AnimGraphPlayer>(target)
            .expect("graph")
            .external_override_owner(),
        None
    );
}

